    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "Sudden out-of-hospital cardiac arrests (OHCA) are significant causes of morbidity and mortality both in the US and worldwide. About 326,200 OHCAs are resuscitated annually by emergency medical services (EMS) with a survival rate of approximately 12% in the US.",
      "reason": "Describes the current state of knowledge regarding OHCA burden and survival rates, and identifies uncertainties/challenges in field settings."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "However, results from clinical trials have been conflicting. Some studies have shown a benefit, while others demonstrated no difference in outcomes using mechanical compressions. Our goal in this systematic review was to synthesize studies comparing outcomes from mechanical and manual CPR during OHCA regardless of presenting rhythm.",
      "reason": "Explains the importance and need for the review by highlighting conflicting trial results and stating the goal to synthesize evidence."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_27",
      "quote": "Lameijer et al and Couper et al conducted meta-analyses of studies conducted only in inpatient settings and reported a definite advantage using mechanical compression.",
      "reason": "Identifies and cites previous similar systematic reviews (meta-analyses) and implies the need for the current review by distinguishing the setting (inpatient vs out-of-hospital)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "The AutoPulse device is a load-distributing band device... The LUCAS device belongs to a different category of piston devices... Theoretically, these mechanical devices should help eliminate the problems associated with fatigue, manpower, and CPR consistency...",
      "reason": "Briefly describes the proposed mechanism of action of the mechanical interventions (load-distributing band, piston, eliminating fatigue)."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence in the retrieved text mentions the use or consideration of a logic model to show hypothesised relationships between intervention components and outcomes."
    }
  ],
  "confidence": 90
}

